/**
 * Cloudflare Turnstile Verification Service
 *
 * Validates Turnstile captcha tokens against Cloudflare Siteverify API.
 * Endpoint: https://challenges.cloudflare.com/turnstile/v0/siteverify
 *
 * In development/test or if CLOUDFLARE_TURNSTILE_SECRET_KEY is not set,
 * this service safely bypasses verification without failing requests.
 */

const TURNSTILE_VERIFY_URL = 'https://challenges.cloudflare.com/turnstile/v0/siteverify'

/**
 * Verifies a Cloudflare Turnstile token.
 *
 * @param {string} token     - The token generated by Turnstile widget on client
 * @param {string} [clientIp] - Client's remote IP address (optional)
 * @returns {Promise<{ success: boolean, bypassed?: boolean, error?: string, errorCodes?: string[] }>}
 */
export async function verifyTurnstileToken(token, clientIp = null) {
  const secretKey = process.env.CLOUDFLARE_TURNSTILE_SECRET_KEY

  // If secret key is not configured, bypass verification (dev / test mode)
  if (!secretKey) {
    return { success: true, bypassed: true }
  }

  if (!token) {
    return {
      success: false,
      error: 'Captcha verification token missing. Please complete the security check.',
      errorCodes: ['missing-input-response'],
    }
  }

  try {
    const formData = new URLSearchParams()
    formData.append('secret', secretKey)
    formData.append('response', token)
    if (clientIp) {
      formData.append('remoteip', clientIp)
    }

    const controller = new AbortController()
    const timeout = setTimeout(() => controller.abort(), 6000)

    const response = await fetch(TURNSTILE_VERIFY_URL, {
      method: 'POST',
      body: formData,
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      signal: controller.signal,
    })
    clearTimeout(timeout)

    const data = await response.json()
    if (data.success) {
      return { success: true, hostname: data.hostname }
    }

    return {
      success: false,
      error: 'Captcha verification failed. Please try again.',
      errorCodes: data['error-codes'] || [],
    }
  } catch (err) {
    console.error('[Turnstile Verification Error]', err.message)
    // Fail-open for temporary network anomalies unless TURNSTILE_STRICT is enabled
    if (process.env.TURNSTILE_STRICT === 'true') {
      return { success: false, error: 'Captcha service temporarily unreachable.' }
    }
    return { success: true, bypassed: true, warning: 'Service unreachable, failed open' }
  }
}
